CREATE OR REPLACE FUNCTION pos.guard_online_commercial_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos', 'auth'
AS $function$
begin
 if (select enabled from pos.online_runtime where singleton) and not pos.online_request_context()
    and not(auth.uid() is null and ((session_user in('postgres','service_role','supabase_admin')
      and coalesce(current_setting('role',true),'none') not in('anon','authenticated'))
     or (coalesce(auth.jwt()->>'role','')='service_role' and current_setting('role',true)='service_role'))) then
  raise exception using errcode='42501',message='ONLINE_COMMAND_REQUIRED';
 end if;
 if TG_OP='DELETE' then return OLD; end if;
 return NEW;
end $function$

CREATE OR REPLACE FUNCTION pos.resolve_screen_permission(p_user_id uuid, p_screen_key text)
 RETURNS TABLE(allowed boolean, source text, role_code text, effect text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pos', 'auth', 'pg_temp'
AS $function$
declare
  v_email text;
  v_role text;
  v_effect text;
  v_allowed boolean;
  v_profile_active boolean := false;
  v_role_configured boolean := false;
begin
  if p_user_id is null or nullif(trim(p_screen_key), '') is null
     or not exists (
       select 1
       from pos.screen_permission_catalog c
       where c.screen_key = p_screen_key
         and c.active
         and c.is_leaf
     ) then
    return query
      select *
      from pos.resolve_screen_permission_precedence(
        false, null, null, null, false
      );
    return;
  end if;

  select u.email into v_email
  from auth.users u
  where u.id = p_user_id;

  v_profile_active := v_email is not null and exists (
    select 1
    from pos.sellers s
    where lower(s.email) = lower(v_email)
      and s.active is true
      and s.deleted_at is null
  );

  if v_profile_active then
    select o.effect into v_effect
    from pos.user_screen_permission_overrides o
    where o.user_id = p_user_id
      and o.screen_key = p_screen_key;

    select a.role_code into v_role
    from pos.user_permission_role_assignments a
    join pos.permission_roles r on r.code = a.role_code and r.active
    where a.user_id = p_user_id
      and a.active;

    if v_role is not null then
      select p.allowed into v_allowed
      from pos.role_screen_permissions p
      where p.role_code = v_role
        and p.screen_key = p_screen_key;
      v_role_configured := found;
    end if;
  end if;

  return query
    select *
    from pos.resolve_screen_permission_precedence(
      v_profile_active, v_effect, v_role, v_allowed, v_role_configured
    );
end;
$function$
